input.command:
mkdir -p /private/tmp/claude/claude-502/-Users-kenneth--claude-spares-spare-y6RR11/cf003aa0-b151-445c-8bb1-ddda0e13feaf/scratchpad/vi && cd $_ && cat > potool.py <<'EOF'
import sys, re
def parse(path):
    text = open(path, encoding='utf-8').read()
    blocks = text.split('\n\n')
    out = []
    for bi, b in enumerate(blocks):
        lines = b.split('\n')
        e = {'bi': bi, 'lines': lines, 'comments': [], 'ctxt': None, 'id': None, 'plural': None}
        cur = None
        for ln in lines:
            if ln.startswith('#'):
                e['comments'].append(ln); cur = None; continue
            m = re.match(r'^(msgctxt|msgid_plural|msgid|msgstr(?:\[\d+\])?) "(.*)"$', ln)
            if m:
                cur = m.group(1); val = m.group(2)
                key = {'msgctxt':'ctxt','msgid':'id','msgid_plural':'plural'}.get(cur)
                if key: e[key] = val
                else: cur = 'str'
                continue
            m = re.match(r'^"(.*)"$', ln)
            if m and cur:
                key = {'msgctxt':'ctxt','msgid':'id','msgid_plural':'plural'}.get(cur)
                if key: e[key] += m.group(1)
        out.append(e)
    return text, blocks, out
if __name__ == '__main__':
    path, dump = sys.argv[1], sys.argv[2]
    _, _, es = parse(path)
    with open(dump, 'w', encoding='utf-8') as f:
        for e in es:
            if e['id'] is None or (e['id'] == '' and e['ctxt'] is None): continue
            f.write(f"@{e['bi']}\n")
            for c in e['comments']:
                if c.startswith('#.') or c.startswith('#,'): f.write(c + '\n')
                elif c.startswith('#:'): f.write(c.replace('../HomeUI/src/','H:').replace('src/components/','') + '\n')
            if e['ctxt'] is not None: f.write(f"CTX {e['ctxt']}\n")
            f.write(f"ID {e['id']}\n")
            if e['plural'] is not None: f.write(f"PL {e['plural']}\n")
EOF
