import sys, re, collections
sys.path.insert(0, '.')
from potool import parse
po, trfile, kind = sys.argv[1], sys.argv[2], sys.argv[3]
tr = {}; notes = {}
cur = None
for ln in open(trfile, encoding='utf-8').read().split('\n'):
    if ln.startswith('@'):
        cur = int(ln[1:]); tr[cur] = None
    elif ln.startswith('#R '):
        notes[cur] = ln[3:]
    elif cur is not None and tr[cur] is None:
        tr[cur] = ln
    elif ln.strip():
        print('extra line', cur, ln); sys.exit(1)
text, blocks, es = parse(po)
PH_N = re.compile(r'%\d+\$[-+ #0]*\d*(?:\.\d+)?[sdgfu]|%[-+ #0]*\d*(?:\.\d+)?[sdgfu]|%\d+%|%%')
def ph_pages(s):
    return sorted(re.findall(r'\{(\w+)[},]', s)) , sorted(re.findall(r'</?\d+/?>', s))
errs = 0
done = 0
for e in es:
    bi = e['bi']
    if e['id'] is None or (e['id'] == '' and e['ctxt'] is None): continue
    if bi not in tr or tr[bi] is None:
        print('MISSING', bi, e['id']); errs += 1; continue
    t = tr[bi]
    src = e['plural'] if e['plural'] is not None else e['id']
    if kind == 'native':
        a = PH_N.findall(src); b = PH_N.findall(t)
        pos = any('$' in x or x.endswith('%') and x != '%%' for x in a)
        if (sorted(a) != sorted(b)) if pos else (a != b):
            if not (e['plural'] is not None and sorted(set(a))==sorted(set(b))):
                print('PH', bi, a, b, src, '|', t); errs += 1
    else:
        if ph_pages(src) != ph_pages(t):
            # plural categories removed: compare sets
            if set(ph_pages(src)[0]) != set(ph_pages(t)[0]) or ph_pages(src)[1] != ph_pages(t)[1]:
                print('PH', bi, ph_pages(src), ph_pages(t)); errs += 1
        if "'" in t: print('APOS', bi, t); errs += 1
    if src.count('\\n') != t.count('\\n'): print('NL', bi); errs += 1
    if (src.startswith(' ') != t.startswith(' ')) or (src.endswith(' ') != t.endswith(' ')): print('SP', bi); errs += 1
    if re.search(r'(?<!\\)"', t): print('QUOTE', bi, t); errs += 1
    lines = e['lines']
    new = []
    inserted = False; skipping = False
    for ln in lines:
        if not inserted and (ln.startswith('#.') or ln.startswith('#:') or ln.startswith('#,') or ln.startswith('msgctxt') or ln.startswith('msgid')):
            new.append('# AI Translated')
            if bi in notes: new.append('# Needs human review: ' + notes[bi])
            inserted = True
        if ln.startswith('msgstr'):
            m = re.match(r'^(msgstr(?:\[\d+\])?) ', ln)
            new.append(f'{m.group(1)} "{t}"'); skipping = True; continue
        if skipping and ln.startswith('"'): continue
        skipping = False
        new.append(ln)
    blocks[bi] = '\n'.join(new); done += 1
if errs: print('ERRORS', errs); sys.exit(1)
open(po, 'w', encoding='utf-8').write('\n\n'.join(blocks))
print('applied', done, 'notes', len([n for n in notes if n in tr]))
EOF
